//! WPT `url/`: every row of `url/resources/urltestdata.json` (read by
//! `url/url-constructor.any.js`), as a table of (name, input, base,
//! expected components or failure).
//!
//! A row is `new URL(input, base)`: failure if `failure` is true, and
//! otherwise ten getters, `href` to `hash`, compared with the row's fields.
//! The `searchParams` field (URLSearchParams serialization) is not kept,
//! and neither is `origin`; see the suite's `SOURCE.md`. The converter
//! checks that the vendored test still says all this.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &["url-constructor.any.js", "urltestdata.json"];

/// Text the test must contain, verbatim.
const REQUIRED: &[&str] = &[
    "const base = expected.base !== null ? expected.base : undefined;",
    "new URL(expected.input, base);",
    "const url = new URL(expected.input, base);",
    "assert_equals(url.href, expected.href, \"href\")",
    "assert_equals(url.protocol, expected.protocol, \"protocol\")",
    "assert_equals(url.username, expected.username, \"username\")",
    "assert_equals(url.password, expected.password, \"password\")",
    "assert_equals(url.host, expected.host, \"host\")",
    "assert_equals(url.hostname, expected.hostname, \"hostname\")",
    "assert_equals(url.port, expected.port, \"port\")",
    "assert_equals(url.pathname, expected.pathname, \"pathname\")",
    "assert_equals(url.search, expected.search, \"search\")",
    "assert_equals(url.hash, expected.hash, \"hash\")",
    "}, `Parsing: <${expected.input}> ${base ? \"against <\" + base + \">\" : \"without base\"}`)",
];

/// The getters compared, in the order of the generated `Expected` fields.
const FIELDS: &[&str] = &[
    "href", "protocol", "username", "password", "host", "hostname", "port", "pathname", "search",
    "hash",
];

struct Case {
    name: String,
    input: String,
    base: Option<String>,
    expected: Option<Vec<String>>,
}

/// Convert the suite in `dir` to the body of a Rust source file.
pub fn convert(dir: &Path) -> Result<String, String> {
    let js = dir.join("url-constructor.any.js");
    let text = std::fs::read_to_string(&js).map_err(|e| format!("{}: {e}", js.display()))?;
    for needle in REQUIRED {
        if !text.contains(needle) {
            return Err(format!(
                "url-constructor.any.js: expected {needle:?}; the test changed upstream"
            ));
        }
    }
    let path = dir.join("urltestdata.json");
    let text = std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
    let json: Value =
        serde_json::from_str(&text).map_err(|e| format!("urltestdata.json: not JSON: {e}"))?;
    let rows = json
        .as_array()
        .ok_or("urltestdata.json: expected a top-level array")?;

    let mut cases = Vec::new();
    for (k, row) in rows.iter().enumerate() {
        if row.is_string() {
            continue;
        }
        let at = |what: &str| format!("urltestdata.json: item {k}: {what}");
        let input = row
            .get("input")
            .and_then(Value::as_str)
            .ok_or_else(|| at("no string \"input\""))?;
        let base = match row.get("base") {
            Some(Value::String(b)) => Some(b.clone()),
            Some(Value::Null) => None,
            _ => return Err(at("\"base\" is not a string or null")),
        };
        let failure = match row.get("failure") {
            None => false,
            Some(Value::Bool(b)) => *b,
            Some(_) => return Err(at("\"failure\" is not a boolean")),
        };
        let expected = if failure {
            None
        } else {
            let mut fields = Vec::new();
            for f in FIELDS {
                let v = row
                    .get(*f)
                    .and_then(Value::as_str)
                    .ok_or_else(|| at(&format!("no string {f:?}")))?;
                fields.push(v.to_owned());
            }
            Some(fields)
        };
        // The test's name, as url-constructor.any.js builds it (an empty
        // base is "without base", as in JavaScript).
        let name = match base.as_deref() {
            Some(b) if !b.is_empty() => format!("Parsing: <{input}> against <{b}>"),
            _ => format!("Parsing: <{input}> without base"),
        };
        cases.push(Case {
            name,
            input: input.to_owned(),
            base,
            expected,
        });
    }
    if cases.is_empty() {
        return Err("urltestdata.json: no rows".into());
    }
    render(&cases)
}

fn render(cases: &[Case]) -> Result<String, String> {
    let mut out = String::new();
    out.push_str(
        "// @generated by `cargo xtask testdata` from tests/data/wpt-urltestdata/.\n\
         // Do not edit: `cargo xtask verify` fails if this differs from what the\n\
         // converter (xtask/src/testdata/wpt_urltestdata.rs) produces.\n\
         // Source, commit and license: tests/data/wpt-urltestdata/SOURCE.md.\n",
    );
    writeln!(out, "// urltestdata.json: {} rows.", cases.len()).map_err(|e| e.to_string())?;
    out.push_str("const URLTESTDATA: &[Case] = &[\n");
    for c in cases {
        let base = match &c.base {
            Some(b) => format!("Some({b:?})"),
            None => "None".to_owned(),
        };
        let expected = match &c.expected {
            Some(f) => {
                let mut e = String::from("Some(Expected {");
                for (name, value) in FIELDS.iter().zip(f) {
                    write!(e, " {name}: {value:?},").map_err(|e| e.to_string())?;
                }
                e.push_str(" })");
                e
            }
            None => "None".to_owned(),
        };
        writeln!(
            out,
            "    Case {{ name: {:?}, input: {:?}, base: {base}, expected: {expected} }},",
            c.name, c.input
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}
